package com.example.rokidgeminisecretary;
import android.app.*;import android.content.*;import android.location.Address;import android.os.*;import android.widget.*;import org.json.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Native phone entry points with real dialogs and synthetic provider requests. */
public final class PhoneNavigationUiChecks {
 interface Work{void run()throws Exception;}interface Bool{boolean get()throws Exception;}
 static Handler ui=new Handler(Looper.getMainLooper());static Activity host;static Context base;static JSONArray cases;
 static void main(Work w)throws Exception{if(Looper.myLooper()==Looper.getMainLooper()){w.run();return;}CountDownLatch l=new CountDownLatch(1);AtomicReference<Throwable> e=new AtomicReference<>();ui.post(()->{try{w.run();}catch(Throwable t){e.set(t);}finally{l.countDown();}});if(!l.await(8,TimeUnit.SECONDS))throw new Exception("phone UI timeout");if(e.get()!=null)throw new Exception(e.get());}
 static Field field(String n)throws Exception{Field f=MainActivity.class.getDeclaredField(n);f.setAccessible(true);return f;}static Object get(Object o,String n)throws Exception{return field(n).get(o);}static void put(Object o,String n,Object v)throws Exception{field(n).set(o,v);}static Object call(Object o,String n,Class<?>[] t,Object...a)throws Exception{Method m=MainActivity.class.getDeclaredMethod(n,t);m.setAccessible(true);return m.invoke(o,a);}static void ok(boolean b,String why)throws Exception{if(!b)throw new Exception(why);}static void await(Bool b,String why)throws Exception{long end=SystemClock.elapsedRealtime()+5000;while(SystemClock.elapsedRealtime()<end){AtomicBoolean yes=new AtomicBoolean();main(()->yes.set(b.get()));if(yes.get())return;Thread.sleep(20);}throw new Exception(why);}
 static class Flow implements AutoCloseable{
 MainActivity owner;TextView status,details;EditText input;AtomicInteger reads=new AtomicInteger(),starts=new AtomicInteger(),commits=new AtomicInteger();volatile boolean block,empty,fail,failCommit;CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);String mode;
 Flow(String mode)throws Exception{this.mode=mode;main(()->{owner=new MainActivity();Method attach=ContextWrapper.class.getDeclaredMethod("attachBaseContext",Context.class);attach.setAccessible(true);attach.invoke(owner,base);((android.content.SharedPreferences)call(owner,"getPreferences",new Class[]{})).edit().putString("map_route_mode",mode).commit();status=new TextView(host);details=new TextView(host);input=new EditText(host);input.setText("合成目的地");put(owner,"status",status);put(owner,"details",details);put(owner,"navigationDestinationInput",input);Address point=new Address(Locale.JAPAN);point.setLatitude(0);point.setLongitude(.01);GoogleNavigationClient.rememberDestination("合成目的地",point);put(owner,"navigationNativeEnvironment",new NavigationNativeEnvironment(host,(op,value)->request(op,value),()->starts.incrementAndGet()));});}
 JSONObject request(String op,String value)throws Exception{if(op.equals("commit")){commits.incrementAndGet();if(failCommit)throw new Exception("synthetic accepted but response lost");return new JSONObject().put("ok",true).put("message","合成開始完了");}int sequence=reads.incrementAndGet();entered.countDown();while(block&&release.getCount()>0)try{release.await();}catch(InterruptedException ignored){}if(sequence!=reads.get())throw new Exception("synthetic superseded provider result");if(fail)throw new Exception("synthetic HTTP failure");if(empty)return new JSONObject().put("choices",new JSONArray());JSONObject route=new JSONObject().put("duration","600s").put("legs",new JSONArray().put(new JSONObject().put("steps",new JSONArray().put(new JSONObject().put("travelMode",mode.equals("transit")?"TRANSIT":mode.toUpperCase(Locale.ROOT))))));if(op.equals("shared")){return ((NavigationRouteChoices)get(owner,"navigationRouteChoices")).publish("合成目的地",mode,"0.0,0.01",new JSONArray().put(route),System.currentTimeMillis());}return new JSONObject().put("token","synthetic").put("legSummary","合成区間").put("choices",new JSONArray().put(new JSONObject().put("id","synthetic").put("label","合成経路").put("review","合成")));}
 void enter(String kind)throws Exception{main(()->{if(kind.equals("shared"))call(owner,"showSharedNavigationRouteChoices",new Class[]{boolean.class},false);else call(owner,"showSavedNavigationPreview",new Class[]{String.class,int.class,int.class},"synthetic",1,0);});}
 AlertDialog dialog(String key)throws Exception{AtomicReference<AlertDialog> d=new AtomicReference<>();await(()->{Object v=get(owner,key);return v instanceof AlertDialog&&((AlertDialog)v).isShowing();},key+" absent");main(()->d.set((AlertDialog)get(owner,key)));return d.get();}
 void choose()throws Exception{AlertDialog d=dialog("navigationChoicesDialog");main(()->d.getListView().performItemClick(d.getListView().getChildAt(0),0,0));dialog("navigationConfirmDialog");}
 void positive()throws Exception{AlertDialog d=dialog("navigationConfirmDialog");main(()->d.getButton(-1).performClick());}
 void cancel()throws Exception{main(()->call(owner,"cancelSavedNavigationPreview",new Class[]{}));}
 String text(){return status.getText().toString()+details.getText().toString();}
 public void close()throws Exception{release.countDown();main(()->call(owner,"disposeNativeNavigationReview",new Class[]{}));}
 }
 static void test(String n,Work w){try{w.run();cases.put(new JSONObject().put("name","phone / "+n).put("pass",true));}catch(Throwable t){while(t.getCause()!=null)t=t.getCause();try{cases.put(new JSONObject().put("name","phone / "+n).put("pass",false).put("failure",t.toString()));}catch(Exception ignored){}}}
 public static JSONArray run(Context c,Activity h)throws Exception{base=c;host=h;cases=new JSONArray();
 for(String mode:new String[]{"walking","bicycling","driving","transit"}){
 test(mode+" shared select-confirm-start",()->{try(Flow f=new Flow(mode)){f.enter("shared");f.choose();f.positive();await(()->f.starts.get()==1,"start absent");ok(f.reads.get()==1,"unexpected provider requery");}});
 test(mode+" shared back cancels",()->{try(Flow f=new Flow(mode)){f.enter("shared");f.choose();main(()->f.dialog("navigationConfirmDialog").cancel());ok(f.starts.get()==0,"cancel started");await(()->f.text().contains("取り消し"),"cancel outcome absent");}});
 }
 for(String kind:new String[]{"shared","saved"}){
 test(kind+" cancel loading ignores late result",()->{try(Flow f=new Flow("transit")){f.block=true;f.enter(kind);ok(f.entered.await(3,TimeUnit.SECONDS),"not entered");f.cancel();f.release.countDown();Thread.sleep(180);main(()->ok(get(f.owner,"navigationChoicesDialog")==null,"late choices opened"));ok(f.starts.get()+f.commits.get()==0,"late start");}});
 test(kind+" choice cancellation",()->{try(Flow f=new Flow("transit")){f.enter(kind);AlertDialog d=f.dialog("navigationChoicesDialog");main(()->d.cancel());await(()->f.text().contains("取り消し"),"no terminal cancel");}});
 for(String phase:new String[]{"loading","choice","confirmation"})test(kind+" dispose at "+phase,()->{try(Flow f=new Flow("transit")){if(phase.equals("loading"))f.block=true;f.enter(kind);if(phase.equals("loading"))ok(f.entered.await(3,TimeUnit.SECONDS),"not started");else if(phase.equals("choice"))f.dialog("navigationChoicesDialog");else f.choose();main(()->call(f.owner,"disposeNativeNavigationReview",new Class[]{}));f.release.countDown();Thread.sleep(120);main(()->{for(String key:new String[]{"navigationLoadingDialog","navigationChoicesDialog","navigationConfirmDialog"})ok(get(f.owner,key)==null,"stale window "+key);});ok(f.starts.get()+f.commits.get()==0,"dispose caused start");}});
 }
 test("shared changed destination terminates",()->{try(Flow f=new Flow("transit")){f.block=true;f.enter("shared");ok(f.entered.await(3,TimeUnit.SECONDS),"not entered");main(()->f.input.setText("合成変更先"));f.release.countDown();await(()->f.text().contains("検索条件が変わりました"),"condition change left waiting");ok(f.starts.get()==0,"changed target started");}});
 test("shared provider failure terminates",()->{try(Flow f=new Flow("transit")){f.fail=true;f.enter("shared");await(()->f.text().contains("取得できません"),"failed wait retained");}});
 test("shared no candidates terminates",()->{try(Flow f=new Flow("transit")){f.empty=true;f.enter("shared");await(()->f.text().contains("候補を確認できません"),"empty wait retained");}});
 test("shared new search discards old response",()->{try(Flow f=new Flow("transit")){f.block=true;f.enter("shared");ok(f.entered.await(3,TimeUnit.SECONDS),"not entered");f.cancel();f.block=false;f.enter("shared");f.dialog("navigationChoicesDialog");f.release.countDown();Thread.sleep(180);f.choose();f.positive();await(()->f.starts.get()==1,"new search failed");}});
 test("saved commit exactly once",()->{try(Flow f=new Flow("transit")){f.enter("saved");f.choose();AlertDialog d=f.dialog("navigationConfirmDialog");main(()->{d.getButton(-1).performClick();d.getButton(-1).performClick();});await(()->f.commits.get()==1,"saved commit missing");await(()->!field("navigationNativeCommitting").getBoolean(f.owner),"commit busy retained");ok(f.commits.get()==1,"duplicate commit");}});

 test("saved stale decision after response never repeats",()->{try(Flow f=new Flow("transit")){f.enter("saved");f.choose();AlertDialog d=f.dialog("navigationConfirmDialog");main(()->d.getButton(-1).performClick());await(()->!field("navigationNativeCommitting").getBoolean(f.owner)&&f.commits.get()==1,"not finished");main(()->d.getButton(-1).performClick());Thread.sleep(120);ok(f.commits.get()==1,"stale decision repeated commit");}});
 test("saved lost response terminates without retry",()->{try(Flow f=new Flow("transit")){f.failCommit=true;f.enter("saved");f.choose();f.positive();await(()->f.text().contains("自動で再送しません"),"lost commit left requesting");ok(f.commits.get()==1,"lost response retried");}});
 for(String mode:new String[]{"walking","bicycling","driving"})test(mode+" saved start",()->{try(Flow f=new Flow(mode)){f.enter("saved");f.choose();f.positive();await(()->f.commits.get()==1,"saved start absent");}});

 for(String phase:new String[]{"loading","choice","confirmation"})test("real host recreation at "+phase,()->{try(Flow f=new Flow("transit")){if(phase.equals("loading"))f.block=true;f.enter("shared");if(phase.equals("loading"))ok(f.entered.await(3,TimeUnit.SECONDS),"not entered");else if(phase.equals("choice"))f.dialog("navigationChoicesDialog");else f.choose();Activity old=host;Class<?> type=old.getClass();AtomicReference<Throwable> failure=new AtomicReference<>();main(()->{type.getField("onDisposed").set(null,(Runnable)()->{try{call(f.owner,"disposeNativeNavigationReview",new Class[]{});}catch(Throwable t){failure.set(t);}});old.recreate();});await(()->type.getField("current").get(null)!=null&&type.getField("current").get(null)!=old,"host not recreated");main(()->host=(Activity)type.getField("current").get(null));f.release.countDown();Thread.sleep(150);ok(failure.get()==null,"disposal failed");main(()->{for(String key:new String[]{"navigationLoadingDialog","navigationChoicesDialog","navigationConfirmDialog"})ok(get(f.owner,key)==null,"recreated host retained stale window");});ok(f.starts.get()==0,"recreation started route");}});

 test("two concurrent start claims admit exactly one",()->{for(int i=0;i<20;i++){SavedRouteTicket ticket=new SavedRouteTicket();String token=ticket.begin("synthetic",1,0,"context",1000);CountDownLatch start=new CountDownLatch(1),done=new CountDownLatch(2);AtomicInteger accepted=new AtomicInteger();for(int worker=0;worker<2;worker++)new Thread(()->{try{start.await();ticket.check(token,"synthetic",1,0,"context",1100);ticket.claim();accepted.incrementAndGet();}catch(Exception expected){}finally{done.countDown();}}).start();start.countDown();ok(done.await(3,TimeUnit.SECONDS),"claim workers stuck");ok(accepted.get()==1,"concurrent double claim");}});
 test("other control replaces choices invalidating old selection",()->{NavigationRouteChoices choices=new NavigationRouteChoices();JSONObject route=new JSONObject().put("duration","600s");JSONObject old=choices.publish("synthetic","walking","0,0",new JSONArray().put(route),1000);String oldId=old.getJSONArray("choices").getJSONObject(0).getString("id");JSONObject newer=choices.publish("synthetic","bicycling","0,0",new JSONArray().put(route),1001);boolean rejected=false;try{choices.select(oldId,"synthetic","walking","0,0",1002);}catch(Exception expected){rejected=true;}ok(rejected,"old control selected stale route");String id=newer.getJSONArray("choices").getJSONObject(0).getString("id");ok(choices.select(id,"synthetic","bicycling","0,0",1002)!=null,"new route unavailable");});
 test("search cancellation rejects late control generation",()->{NavigationSearchEpoch epoch=new NavigationSearchEpoch();long old=epoch.begin();epoch.cancel();long fresh=epoch.begin();boolean rejected=false;try{epoch.require(old);}catch(InterruptedException expected){rejected=true;}ok(rejected,"cancelled provider result admitted");epoch.require(fresh);});
 return cases;}
}
